const countryAliases={'espana':'Spain','spain':'Spain','eslovaquia':'Slovakia','slovakia':'Slovakia','alemania':'Germany','germany':'Germany','austria':'Austria','francia':'France','france':'France','italia':'Italy','italy':'Italy','reino unido':'United Kingdom','united kingdom':'United Kingdom','inglaterra':'United Kingdom','estados unidos':'United States','eeuu':'United States','usa':'United States','united states':'United States','canada':'Canada','rusia':'Russia','russia':'Russia','china':'China','india':'India','brasil':'Brazil','brazil':'Brazil','mexico':'Mexico','australia':'Australia','polonia':'Poland','poland':'Poland','hungria':'Hungary','hungary':'Hungary','chequia':'Czechia','republica checa':'Czechia','czechia':'Czechia','rumania':'Romania','romania':'Romania','bulgaria':'Bulgaria','portugal':'Portugal','irlanda':'Ireland','ireland':'Ireland','suiza':'Switzerland','switzerland':'Switzerland','suecia':'Sweden','sweden':'Sweden','noruega':'Norway','norway':'Norway','finlandia':'Finland','finland':'Finland','dinamarca':'Denmark','denmark':'Denmark','islandia':'Iceland','iceland':'Iceland','belgica':'Belgium','belgium':'Belgium','paises bajos':'Netherlands','netherlands':'Netherlands','grecia':'Greece','greece':'Greece','turquia':'Türkiye','turkey':'Türkiye','japon':'Japan','japan':'Japan','corea del sur':'South Korea','south korea':'South Korea','marruecos':'Morocco','morocco':'Morocco','argelia':'Algeria','algeria':'Algeria','egipto':'Egypt','egypt':'Egypt','sudafrica':'South Africa','south africa':'South Africa','nueva zelanda':'New Zealand','new zealand':'New Zealand','cuba':'Cuba'};
function normSearch(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}
function fitRecords(rows,maxZoom=7){if(!rows.length)return false;const bounds=L.latLngBounds(rows.map(x=>[x.lat,x.lng]));if(rows.length===1)map.flyTo([rows[0].lat,rows[0].lng],Math.min(maxZoom,10));else map.flyToBounds(bounds.pad(.18),{maxZoom,duration:1.1});return true}
function showPlaceDirectory(title,rows,kind){const es=currentLang==='es',counts={};rows.forEach(x=>counts[x.type]=(counts[x.type]||0)+1);const order=['school','university','language','association','cervantes','teacher','official'];const chips=order.filter(t=>counts[t]).map(t=>'<span class="dirStat type-'+t+'"><i></i><b>'+counts[t]+'</b> '+publicTypeLabel(t)+'</span>').join('');const cities=kind==='country'?[...new Set(rows.map(x=>x.city).filter(Boolean))].length:null;const list=[...rows].sort((x,y)=>(x.city||'').localeCompare(y.city||'')||(x.name||'').localeCompare(y.name||'')).slice(0,250);detail.innerHTML='<div class="placeDirectory"><div class="dirEyebrow">ATLAS ELE · '+(kind==='country'?(es?'PAÍS':'COUNTRY'):(es?'CIUDAD':'CITY'))+'</div><h2>'+title+'</h2><div class="dirHeadline"><strong>'+rows.length.toLocaleString()+'</strong><span>'+(es?'instituciones':'institutions')+(cities!==null?' · '+cities+' '+(es?'ciudades':'cities'):'')+'</span></div><div class="dirStats">'+chips+'</div><div class="dirList">'+list.map(x=>'<button data-dir-id="'+x.id+'"><i class="dirDot type-'+x.type+'"></i><span><strong>'+x.name+'</strong><small>'+x.city+(kind==='city'?' · '+x.country:'')+'</small></span><em>›</em></button>').join('')+'</div>'+(rows.length>250?'<div class="dirMore">'+(es?'Mostrando los primeros 250 resultados':'Showing first 250 results')+'</div>':'')+'</div>';panel.style.display='block';detail.querySelectorAll('[data-dir-id]').forEach(btn=>btn.onclick=()=>{const x=data.find(r=>r.id===btn.dataset.dirId);if(x){map.flyTo([x.lat,x.lng],15,{duration:.8});show(x)}})}
function search(){const raw=document.getElementById('q').value.trim();if(!raw)return;const q=normSearch(raw),canonical=countryAliases[q]||null;const countries=canonical?data.filter(x=>x.country===canonical):data.filter(x=>normSearch(x.country)===q);if(countries.length){fitRecords(countries,6);showPlaceDirectory(canonical||countries[0].country,countries,'country');return}const cities=data.filter(x=>normSearch(x.city)===q);if(cities.length){fitRecords(cities,12);showPlaceDirectory(cities[0].city,cities,'city');return}const hit=data.find(x=>normSearch(x.name)===q)||data.find(x=>normSearch(x.name).includes(q));if(hit){map.flyTo([hit.lat,hit.lng],15,{duration:1.1});show(hit)}}
const searchSuggest=document.getElementById('searchSuggest');function suggestionIcon(type){return {school:'▣',university:'◆',language:'●',association:'●',cervantes:'●',teacher:'♥'}[type]||'•'}function buildSearchSuggestions(){const raw=document.getElementById('q').value.trim(),q=normSearch(raw);if(q.length<2){searchSuggest.classList.remove('open');searchSuggest.innerHTML='';return}const items=[],seen=new Set();const aliases=Object.entries(countryAliases).filter(([a])=>normSearch(a).includes(q)).slice(0,3);for(const [,country] of aliases){if(seen.has('c'+country))continue;seen.add('c'+country);const rows=data.filter(x=>x.country===country);if(rows.length)items.push({kind:'country',label:country,sub:rows.length+' '+(currentLang==='es'?'instituciones':'institutions'),rows})}const countryNames=[...new Set(data.map(x=>x.country))].filter(x=>normSearch(x).includes(q)).slice(0,3);for(const country of countryNames){if(seen.has('c'+country))continue;seen.add('c'+country);const rows=data.filter(x=>x.country===country);items.push({kind:'country',label:country,sub:rows.length+' '+(currentLang==='es'?'instituciones':'institutions'),rows})}const cityNames=[...new Set(data.map(x=>x.city).filter(Boolean))].filter(x=>normSearch(x).includes(q)).slice(0,5);for(const city of cityNames){const rows=data.filter(x=>x.city===city);items.push({kind:'city',label:city,sub:rows[0]?.country+' · '+rows.length+' '+(currentLang==='es'?'instituciones':'institutions'),rows})}data.filter(x=>normSearch(x.name).includes(q)).slice(0,7).forEach(x=>items.push({kind:'record',label:x.name,sub:x.city+', '+x.country,row:x,type:x.type}));const final=items.slice(0,10);searchSuggest.innerHTML=final.map((x,i)=>'<button data-si="'+i+'"><b class="'+(x.type?'type-'+x.type:'')+'">'+(x.kind==='country'?'🌍':x.kind==='city'?'📍':suggestionIcon(x.type))+'</b><span><strong>'+x.label+'</strong><small>'+x.sub+'</small></span><em>'+(x.kind==='country'?(currentLang==='es'?'País':'Country'):x.kind==='city'?(currentLang==='es'?'Ciudad':'City'):publicTypeLabel(x.type))+'</em></button>').join('');searchSuggest.classList.toggle('open',!!final.length);searchSuggest.querySelectorAll('[data-si]').forEach(btn=>btn.onclick=()=>{const x=final[+btn.dataset.si];searchSuggest.classList.remove('open');document.getElementById('q').value=x.label;if(x.kind==='country'){fitRecords(x.rows,6);showPlaceDirectory(x.label,x.rows,'country')}else if(x.kind==='city'){fitRecords(x.rows,12);showPlaceDirectory(x.label,x.rows,'city')}else{map.flyTo([x.row.lat,x.row.lng],15,{duration:.8});show(x.row)}})}document.getElementById('q').addEventListener('input',buildSearchSuggestions);document.getElementById('q').addEventListener('focus',buildSearchSuggestions);document.addEventListener('click',e=>{if(!e.target.closest('.search'))searchSuggest.classList.remove('open')});
document.getElementById('searchBtn').onclick=search;document.getElementById('q').addEventListener('keydown',e=>{if(e.key==='Enter')search()});
