let globeInstance=null;
const typeColors={school:'#0878d1',university:'#7836ce',language:'#f38b20',association:'#16a66c',teacher:'#eb218e',cervantes:'#d92525'};
function getGlobePoints(source=data){
 const groups=new Map();
 source.forEach(x=>{const key=(+x.lat).toFixed(4)+'|'+(+x.lng).toFixed(4);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(x)});
 return [...groups.values()].map(items=>{if(items.length===1)return {...items[0],count:1,items};const counts={};items.forEach(x=>counts[x.type]=(counts[x.type]||0)+1);const type=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0][0];return {...items[0],type,count:items.length,items,name:items.length+' places'}});
}
function initGlobe(){
 if(globeInstance)return;
 const el=document.getElementById('globeView');
 globeInstance=Globe()(el)
  .globeImageUrl('https://unpkg.com/three-globe/example/img/earth-blue-marble.jpg')
  .bumpImageUrl('https://unpkg.com/three-globe/example/img/earth-topology.png')
  .backgroundImageUrl('https://unpkg.com/three-globe/example/img/night-sky.png')
  .pointsData(getGlobePoints())
  .pointLat(d=>d.lat).pointLng(d=>d.lng).pointColor(d=>typeColors[d.type]||'#0878d1')
  .pointAltitude(d=>.004+Math.min(d.count||1,20)*.00035).pointRadius(d=>.09+Math.min(Math.sqrt(d.count||1)*.035,.16))
  .pointResolution(10)
  .pointLabel(d=>'<div class="globe-tooltip"><b>'+((d.count||1)>1?(d.count+' places'):d.name)+'</b><small>📍 '+d.city+', '+d.country+((d.count||1)>1?'<br>Click to explore this cluster':'<br>🇪🇸 '+d.program)+'</small></div>')
  .onPointClick(d=>{if((d.count||1)>1){setViewMode('2d');map.flyTo([d.lat,d.lng],12,{duration:1.1})}else show(d)});
 globeInstance.controls().autoRotate=true;globeInstance.controls().autoRotateSpeed=.32;
 globeInstance.pointOfView({lat:28,lng:8,altitude:2.15},1200);
 const resize=()=>{globeInstance.width(el.clientWidth).height(el.clientHeight)};resize();window.addEventListener('resize',resize);
}
function setViewMode(mode){
 const is3=mode==='3d';document.body.classList.toggle('globe-mode',is3);document.getElementById('globeView').classList.toggle('active',is3);
 document.getElementById('map2d').classList.toggle('active',!is3);document.getElementById('globe3d').classList.toggle('active',is3);
 if(is3){initGlobe();setTimeout(()=>{const el=document.getElementById('globeView');globeInstance.width(el.clientWidth).height(el.clientHeight)},50)}else{setTimeout(()=>map.invalidateSize(),50)}
}
document.getElementById('globe3d').onclick=()=>setViewMode('3d');
document.getElementById('map2d').onclick=()=>setViewMode('2d');

function initMiniGlobe(){
 const el=document.getElementById('miniGlobe'); if(!el || typeof Globe!=='function') return;
 try{
  const g=Globe()(el)
   .width(58).height(58)
   .globeImageUrl('https://unpkg.com/three-globe/example/img/earth-blue-marble.jpg')
   .bumpImageUrl('https://unpkg.com/three-globe/example/img/earth-topology.png')
   .backgroundColor('rgba(0,0,0,0)')
   .showAtmosphere(true).atmosphereColor('#7ad9ff').atmosphereAltitude(.12);
  g.pointOfView({lat:20,lng:-10,altitude:1.75},0);
  const ctl=g.controls();ctl.autoRotate=true;ctl.autoRotateSpeed=.8;ctl.enableZoom=false;ctl.enablePan=false;ctl.enableRotate=false;
 }catch(e){ el.textContent='🌍'; el.style.fontSize='42px'; el.style.display='grid'; el.style.placeItems='center'; }
}
initMiniGlobe();

async function loadPublicMapData(){
 try{
  const r=await fetch('data/pilot-city-points.json?v=2',{cache:'no-store'});if(!r.ok)throw new Error('data '+r.status);
  const payload=await r.json();const pilot=(payload.institutions||[]).map(x=>({...x,program:x.program||'Spanish / ELE',verified:x.verified??false,web:x.web||''}));
  const spain=(window.ATLAS_SPAIN||[]).map(a=>({id:a[0],name:a[1],type:a[2],city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:a[8],address:a[9]||'',precision:a[10]||'city',program:'Spanish / ELE'}));
  const central=(window.ATLAS_CENTRAL||[]).map(a=>({id:a[0],name:a[1],type:a[2],city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:a[8],precision:'city',program:'Spanish / ELE'}));
  const globalSeed=(window.ATLAS_GLOBAL||[]).map(a=>({id:a[0],name:a[1],type:a[2],city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:a[8],precision:'city',program:'Spanish / ELE'}));const cervantes=(window.ATLAS_CERVANTES||[]).map(a=>({id:a[0],name:a[1],type:'cervantes',city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:true,precision:'city',program:'Instituto Cervantes network'}));const accredited=(window.ATLAS_ACCREDITED||[]).map(a=>({id:a[0],name:a[1],type:a[2],city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:a[8],address:a[9]||'',precision:'address',program:'Spanish / ELE',accreditation:'Instituto Cervantes Accredited'}));const ukMaster=(window.ATLAS_UK_MASTER||[]).map(a=>({id:a[0],name:a[1],type:a[2],city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:a[8],precision:'region',program:'Spanish / MFL'}));const ukMaster2=(window.ATLAS_UK_MASTER_2||[]).map(a=>({id:a[0],name:a[1],type:a[2],city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:a[8],precision:'region',program:'Spanish / MFL'}));const ukMaster3=(window.ATLAS_UK_MASTER_3||[]).map(a=>({id:a[0],name:a[1],type:a[2],city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:a[8],precision:'region',program:'Spanish / MFL'}));const ukMaster4=(window.ATLAS_UK_MASTER_4||[]).map(a=>({id:a[0],name:a[1],type:a[2],city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:a[8],precision:'region',program:'Spanish / MFL'}));const ukMaster5=(window.ATLAS_UK_MASTER_5||[]).map(a=>({id:a[0],name:a[1],type:a[2],city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:a[8],precision:'region',program:'Spanish / MFL'}));const ukMaster6=(window.ATLAS_UK_MASTER_6||[]).map(a=>({id:a[0],name:a[1],type:a[2],city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:a[8],precision:'region',program:'Spanish / MFL'}));const masterEurope=(window.ATLAS_MASTER_EUROPE||[]).map(a=>({id:a[0],name:a[1],type:a[2],city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:a[8],precision:'city',program:'Spanish / ELE'}));let packedMaster=[];try{const parts=window.ATLAS_PACKED_PARTS||[];if(parts.length>=8){const b64=parts.join('');const bin=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));const ds=new DecompressionStream('deflate');const txt=await new Response(new Blob([bin]).stream().pipeThrough(ds)).text();packedMaster=JSON.parse(txt).map(a=>({id:a[0],name:a[1],type:a[2],city:a[3],country:a[4],lat:a[5],lng:a[6],web:a[7]||'',verified:a[8],precision:a[9]||'city',program:'Spanish / MFL'}));console.info('[ATLAS] packed master loaded',packedMaster.length)}}catch(e){console.error('[ATLAS] packed master failed',e)}
  const byId=new Map();
  const precisionRank={unknown:0,country:1,region:2,city:3,address:4,exact:5};
  function mergeRecord(x,source){
    const old=byId.get(x.id);
    if(!old){byId.set(x.id,{...x,_source:source});return}
    const oldRank=precisionRank[old.precision||'unknown']||0,newRank=precisionRank[x.precision||'unknown']||0;
    if(newRank>oldRank){console.info('[ATLAS] upgraded location',x.id,old.precision,'→',x.precision,source);byId.set(x.id,{...old,...x,_source:source});return}
    if(newRank===oldRank){
      const merged={...old};
      for(const [k,v] of Object.entries(x)){if((merged[k]===undefined||merged[k]===null||merged[k]==='')&&v!==undefined&&v!==null&&v!=='')merged[k]=v}
      byId.set(x.id,merged);console.warn('[ATLAS] duplicate ID kept first location',x.id,old._source,'vs',source);return
    }
    console.warn('[ATLAS] protected higher-precision location',x.id,old.precision,'from',x.precision,source);
  }
  pilot.forEach(x=>mergeRecord(x,'pilot'));spain.forEach(x=>mergeRecord(x,'spain'));central.forEach(x=>mergeRecord(x,'central-europe'));globalSeed.forEach(x=>{if(/(?:Instituto|Aula|Extensión|Antena|Cátedra) Cervantes/i.test(x.name))x.type='cervantes';mergeRecord(x,'global-seed')});cervantes.forEach(x=>mergeRecord(x,'cervantes-2025'));accredited.forEach(x=>mergeRecord(x,'cervantes-accredited'));ukMaster.forEach(x=>mergeRecord(x,'uk-master'));ukMaster2.forEach(x=>mergeRecord(x,'uk-master-2'));ukMaster3.forEach(x=>mergeRecord(x,'uk-master-3'));ukMaster4.forEach(x=>mergeRecord(x,'uk-master-4'));ukMaster5.forEach(x=>mergeRecord(x,'uk-master-5'));ukMaster6.forEach(x=>mergeRecord(x,'uk-master-6'));masterEurope.forEach(x=>mergeRecord(x,'master-europe'));packedMaster.forEach(x=>mergeRecord(x,'master-packed'));data=[...byId.values()];const fd=window.ATLAS_FEDELE;if(fd){const normF=v=>(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();for(const [name,city] of fd.members){const n=normF(name),c=normF(city);const hit=data.find(x=>x.country==='Spain'&&normF(x.city)===c&&(normF(x.name)===n||normF(x.name).includes(n)||n.includes(normF(x.name))));if(hit){hit.fedele=true;hit.accreditation=hit.accreditation||'Instituto Cervantes Accredited'}}const a=fd.association;if(!data.some(x=>x.id==='ES-FEDELE-001'))data.push({id:'ES-FEDELE-001',name:a[0],type:a[1],city:a[2],country:a[3],lat:a[4],lng:a[5],web:a[6],address:a[7],verified:true,precision:'address',program:'Federación de Escuelas de Español como Lengua Extranjera',fedele:true});for(const a of (window.ATLAS_FEDELE_ANDALUCIA||[])){const [name,type,city,country,lat,lng,web,phone,address]=a,n=normF(name),c=normF(city);let hit=data.find(x=>x.country===country&&normF(x.city)===c&&(normF(x.name)===n||normF(x.name).includes(n)||n.includes(normF(x.name))));if(hit){hit.fedele=true;hit.accreditation=hit.accreditation||'Instituto Cervantes Accredited';hit.web=hit.web||web;hit.phone=hit.phone||phone;hit.address=hit.address||address;if((precisionRank[hit.precision||'unknown']||0)<4){hit.lat=lat;hit.lng=lng;hit.precision='address'}}else data.push({id:'ES-FEDELE-A-'+String(data.length+1),name,type,city,country,lat,lng,web,phone,address,verified:true,precision:'address',program:'Spanish / ELE',fedele:true,accreditation:'Instituto Cervantes Accredited'})}}
  for(const a of (window.ATLAS_FEDELE_ANDALUCIA_2||[])){const [name,type,city,country,lat,lng,web]=a;const nf=v=>(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(),n=nf(name),ct=nf(city);let hit=data.find(x=>x.country===country&&nf(x.city)===ct&&(nf(x.name)===n||nf(x.name).includes(n)||n.includes(nf(x.name))));if(hit){hit.fedele=true;hit.accreditation=hit.accreditation||'Instituto Cervantes Accredited';hit.web=hit.web||web}else data.push({id:'ES-FEDELE-B-'+(data.length+1),name,type,city,country,lat,lng,web,verified:true,precision:'city',program:'Spanish / ELE',fedele:true,accreditation:'Instituto Cervantes Accredited'})}
  render();
  const hs=document.querySelectorAll('.headlineStats strong');if(hs[0])hs[0].textContent=data.length.toLocaleString();if(hs[1])hs[1].textContent=new Set(data.map(x=>x.country)).size;
  const ms=document.querySelectorAll('.mini-stats strong');if(ms[0])ms[0].textContent=data.length.toLocaleString();if(ms[1])ms[1].textContent=new Set(data.map(x=>x.country)).size;
  if(globeInstance)globeInstance.pointsData(getGlobePoints());
 }catch(e){console.error('ATLAS ELE data load failed',e)}
}
loadPublicMapData();

const teacherJoinForm=document.getElementById('teacherJoinForm');document.getElementById('teacherRegisterBtn').onclick=()=>teacherJoinForm.classList.toggle('open');function pendingSubmissions(){try{return JSON.parse(localStorage.getItem('atlasPendingTeachers')||'[]')}catch(e){return[]}}function savePendingSubmissions(v){localStorage.setItem('atlasPendingTeachers',JSON.stringify(v));updatePendingCount()}function updatePendingCount(){const n=pendingSubmissions().length,e=document.getElementById('pendingCount');if(e)e.textContent=n;const t=document.getElementById('adminTeachers');if(t)t.textContent=n}teacherJoinForm.onsubmit=e=>{e.preventDefault();const v=pendingSubmissions();v.push({id:'SUB-'+Date.now(),name:document.getElementById('tjName').value.trim(),email:document.getElementById('tjEmail').value.trim(),institution:document.getElementById('tjInstitution').value.trim(),city:document.getElementById('tjCity').value.trim(),country:document.getElementById('tjCountry').value.trim(),visibility:document.getElementById('tjVisibility').value,web:document.getElementById('tjWeb').value.trim(),status:'pending',submitted:new Date().toISOString()});savePendingSubmissions(v);teacherJoinForm.reset();document.getElementById('tjStatus').textContent=currentLang==='es'?'✓ Solicitud enviada para revisión':'✓ Submitted for review'};updatePendingCount();
