document.getElementById('adminBtn').onclick=()=>{adminPanel.classList.add('open');teacherCard.classList.remove('open');document.getElementById('adminInstitutions').textContent=data.length.toLocaleString();document.getElementById('adminCountries').textContent=new Set(data.map(x=>x.country)).size};
document.getElementById('adminClose').onclick=()=>adminPanel.classList.remove('open');

function savedIds(){try{return JSON.parse(localStorage.getItem('atlasSaved')||'[]')}catch(e){return[]}}function isSaved(id){return savedIds().includes(id)}function updateMyAtlasCount(){const e=document.getElementById('myAtlasCount');if(e)e.textContent=savedIds().length}function toggleSaved(id){let v=savedIds();v=v.includes(id)?v.filter(x=>x!==id):[...v,id];localStorage.setItem('atlasSaved',JSON.stringify(v));updateMyAtlasCount();renderMyAtlas()}function myAtlasRows(){const set=new Set(savedIds());return data.filter(x=>set.has(x.id))}const cityBrowser=document.getElementById('cityBrowser');function cityCounts(){const m=new Map();data.forEach(x=>{if(!x.city)return;const k=x.city+'|'+x.country;if(!m.has(k))m.set(k,{city:x.city,country:x.country,count:0});m.get(k).count++});return [...m.values()].sort((a,b)=>b.count-a.count||a.city.localeCompare(b.city))}function renderCityBrowser(){const q=normSearch(document.getElementById('cityBrowserSearch')?.value||''),rows=cityCounts().filter(x=>!q||normSearch(x.city).includes(q)||normSearch(x.country).includes(q)),el=document.getElementById('cityBrowserList');if(!el)return;el.innerHTML=rows.slice(0,300).map((x,i)=>'<button data-city-open="'+encodeURIComponent(x.city)+'" data-city-country="'+encodeURIComponent(x.country)+'"><span class="cbRank">'+(i+1)+'</span><b>'+countryFlag(x.country)+'</b><span><strong>'+x.city+'</strong><small>'+x.country+' · '+x.count.toLocaleString()+' '+(currentLang==='es'?'instituciones':'institutions')+'</small></span><em>›</em></button>').join('');el.querySelectorAll('[data-city-open]').forEach(b=>b.onclick=()=>{const city=decodeURIComponent(b.dataset.cityOpen),country=decodeURIComponent(b.dataset.cityCountry),rs=data.filter(x=>x.city===city&&x.country===country);cityBrowser.classList.remove('open');fitRecords(rs,12);showPlaceDirectory(city,rs,'city')})}document.getElementById('browseCitiesBtn').onclick=()=>{document.getElementById('moreMenu').classList.remove('open');document.getElementById('cityBrowserSearch').value='';renderCityBrowser();cityBrowser.classList.add('open')};document.getElementById('cityBrowserClose').onclick=()=>cityBrowser.classList.remove('open');document.getElementById('cityBrowserSearch').oninput=renderCityBrowser;
const countryBrowser=document.getElementById('countryBrowser');function countryFlag(country){const map={'Spain':'🇪🇸','Slovakia':'🇸🇰','United Kingdom':'🇬🇧','United States':'🇺🇸','Germany':'🇩🇪','France':'🇫🇷','Italy':'🇮🇹','Austria':'🇦🇹','Canada':'🇨🇦','Mexico':'🇲🇽','Brazil':'🇧🇷','Argentina':'🇦🇷','Portugal':'🇵🇹','Netherlands':'🇳🇱','Belgium':'🇧🇪','Switzerland':'🇨🇭','Poland':'🇵🇱','Czechia':'🇨🇿','Hungary':'🇭🇺','Romania':'🇷🇴','Japan':'🇯🇵','China':'🇨🇳','India':'🇮🇳','Australia':'🇦🇺','Russia':'🇷🇺','South Korea':'🇰🇷','Ireland':'🇮🇪','Sweden':'🇸🇪','Norway':'🇳🇴','Finland':'🇫🇮','Denmark':'🇩🇰','Greece':'🇬🇷','Croatia':'🇭🇷','Slovenia':'🇸🇮','Serbia':'🇷🇸'};return map[country]||'🌐'}function countryCounts(){const m=new Map();data.forEach(x=>{if(x.country)m.set(x.country,(m.get(x.country)||0)+1)});return [...m].map(([country,count])=>({country,count})).sort((a,b)=>b.count-a.count||a.country.localeCompare(b.country))}function renderCountryBrowser(){const q=normSearch(document.getElementById('countryBrowserSearch')?.value||''),rows=countryCounts().filter(x=>!q||normSearch(x.country).includes(q)),el=document.getElementById('countryBrowserList');if(!el)return;el.innerHTML=rows.map((x,i)=>'<button data-country-open="'+x.country+'"><span class="cbRank">'+(i+1)+'</span><b>'+countryFlag(x.country)+'</b><span><strong>'+x.country+'</strong><small>'+x.count.toLocaleString()+' '+(currentLang==='es'?'instituciones':'institutions')+'</small></span><em>›</em></button>').join('');el.querySelectorAll('[data-country-open]').forEach(b=>b.onclick=()=>{const rows=data.filter(x=>x.country===b.dataset.countryOpen);countryBrowser.classList.remove('open');fitRecords(rows,6);showPlaceDirectory(b.dataset.countryOpen,rows,'country')})}document.getElementById('browseCountriesBtn').onclick=()=>{document.getElementById('moreMenu').classList.remove('open');document.getElementById('countryBrowserSearch').value='';renderCountryBrowser();countryBrowser.classList.add('open')};document.getElementById('countryBrowserClose').onclick=()=>countryBrowser.classList.remove('open');document.getElementById('countryBrowserSearch').oninput=renderCountryBrowser;
const myAtlasPanel=document.getElementById('myAtlasPanel');function renderMyAtlas(){const rows=myAtlasRows(),el=document.getElementById('myAtlasList');if(!el)return;el.innerHTML=rows.length?rows.map(x=>'<div class="myAtlasItem"><button data-ma-open="'+x.id+'"><i class="dirDot type-'+x.type+'"></i><span><strong>'+x.name+'</strong><small>'+x.city+', '+x.country+'</small></span></button><button class="maRemove" data-ma-remove="'+x.id+'">×</button></div>').join(''):'<div class="pendingEmpty">♡ '+(currentLang==='es'?'Todavía no has guardado instituciones':'No saved institutions yet')+'</div>';el.querySelectorAll('[data-ma-open]').forEach(b=>b.onclick=()=>{const x=data.find(r=>r.id===b.dataset.maOpen);if(x){myAtlasPanel.classList.remove('open');map.flyTo([x.lat,x.lng],15,{duration:.8});show(x)}});el.querySelectorAll('[data-ma-remove]').forEach(b=>b.onclick=()=>toggleSaved(b.dataset.maRemove));updateMyAtlasCount()}document.getElementById('myAtlasBtn').onclick=()=>{renderMyAtlas();myAtlasPanel.classList.add('open');adminPanel.classList.remove('open');teacherCard.classList.remove('open')};document.getElementById('myAtlasClose').onclick=()=>myAtlasPanel.classList.remove('open');document.getElementById('myAtlasClear').onclick=()=>{localStorage.removeItem('atlasSaved');renderMyAtlas()};function downloadMyAtlasCsv(){const rows=myAtlasRows();if(!rows.length)return;const fields=exportFields(),out=[fields.join(','),...rows.map(x=>fields.map(f=>'"'+String(x[f]??'').replace(/"/g,'""')+'"').join(','))];const blob=new Blob([out.join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='My_ATLAS_ELE.csv';a.click();URL.revokeObjectURL(a.href)}function downloadMyAtlasXlsx(){const rows=myAtlasRows();if(!rows.length)return;const fields=exportFields(),out=rows.map(x=>Object.fromEntries(fields.map(f=>[f,x[f]??''])));const ws=XLSX.utils.json_to_sheet(out),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'My Atlas');XLSX.writeFile(wb,'My_ATLAS_ELE.xlsx')}document.getElementById('myAtlasCsv').onclick=downloadMyAtlasCsv;document.getElementById('myAtlasXlsx').onclick=downloadMyAtlasXlsx;updateMyAtlasCount();
const contactPanel=document.getElementById('contactPanel');
document.getElementById('contactBtn').onclick=()=>{contactPanel.classList.add('open');adminPanel.classList.remove('open');teacherCard.classList.remove('open')};
document.getElementById('contactClose').onclick=()=>contactPanel.classList.remove('open');

document.getElementById('contactForm').addEventListener('submit',e=>{e.preventDefault();const name=document.getElementById('contactName').value.trim(),email=document.getElementById('contactEmail').value.trim(),subject=document.getElementById('contactSubject').value.trim(),message=document.getElementById('contactMessage').value.trim();const body=(currentLang==='es'?'Nombre: ':'Name: ')+name+'\nEmail: '+email+'\n\n'+message;window.location.href='mailto:info@atlasele.org?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)});

const adminWorkspace=document.getElementById('adminWorkspace'),adminGrid=document.querySelector('.adminGrid');
function qualityIssue(x){if(!Number.isFinite(+x.lat)||!Number.isFinite(+x.lng)||(+x.lat===0&&+x.lng===0))return 'invalid';if((x.precision||'unknown')==='region')return 'region';if((x.precision||'unknown')==='city')return 'city';if(!x.web)return 'web';return null}function updateQualityPriority(){const el=document.getElementById('qualityPriority');if(!el)return;const labels=currentLang==='es'?{invalid:'Coordenadas inválidas',region:'Ubicación regional',city:'Solo ciudad',web:'Sin web'}:{invalid:'Invalid coordinates',region:'Region-level',city:'City-level only',web:'Missing website'};const icons={invalid:'🔴',region:'🟠',city:'🟡',web:'⚪'};el.innerHTML=['invalid','region','city','web'].map(k=>{const n=data.filter(x=>qualityIssue(x)===k).length;return '<button data-quality-issue="'+k+'"><span>'+icons[k]+'</span><b>'+n.toLocaleString()+'</b><small>'+labels[k]+'</small></button>'}).join('');el.querySelectorAll('[data-quality-issue]').forEach(b=>b.onclick=()=>renderQualityIssue(b.dataset.qualityIssue))}function renderQualityIssue(issue){const rows=data.filter(x=>qualityIssue(x)===issue),el=document.getElementById('adminTable');const labels=currentLang==='es'?{invalid:'Coordenadas inválidas',region:'Ubicación regional',city:'Ubicación solo por ciudad',web:'Registros sin web'}:{invalid:'Invalid coordinates',region:'Region-level locations',city:'City-level locations',web:'Records missing website'};document.getElementById('adminWorkTitle').textContent=labels[issue];document.getElementById('adminWorkSub').textContent=rows.length.toLocaleString()+' '+(currentLang==='es'?'registros para revisar':'records to review');el.innerHTML=rows.slice(0,500).map(x=>'<div class="adminRow quality-'+issue+'"><div><strong>'+x.name+'</strong><small>'+x.city+', '+x.country+' · '+(x.precision||'unknown')+'</small></div><span class="type">'+x.type+'</span><button data-edit="'+x.id+'">✎</button></div>').join('');el.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editAdminRecord(b.dataset.edit))}
function duplicateKeyName(v){return normSearch(v||'').replace(/\b(university|universidad|universite|universitat|universita|school|colegio|college|academy|academia|instituto|institute|language|languages|spanish|espanol|español|the|of|de|del|la|el)\b/g,' ').replace(/\s+/g,' ').trim()}function possibleDuplicates(){const groups=new Map();data.forEach(x=>{const n=duplicateKeyName(x.name);if(n.length<4)return;const k=n+'|'+normSearch(x.city||'')+'|'+normSearch(x.country||'');if(!groups.has(k))groups.set(k,[]);groups.get(k).push(x)});return [...groups.values()].filter(g=>g.length>1)}function updateDuplicateCount(){const e=document.getElementById('duplicateCount');if(e)e.textContent=possibleDuplicates().reduce((n,g)=>n+g.length,0)}function renderDuplicates(){const groups=possibleDuplicates(),el=document.getElementById('adminTable');document.getElementById('adminWorkTitle').textContent=currentLang==='es'?'Posibles duplicados':'Possible duplicates';document.getElementById('adminWorkSub').textContent=currentLang==='es'?'Revisión manual: nunca se elimina automáticamente':'Manual review — nothing is deleted automatically';el.innerHTML=groups.length?groups.slice(0,150).map(g=>'<div class="duplicateGroup"><div class="dupHead"><b>⚠ '+g.length+' '+(currentLang==='es'?'registros similares':'similar records')+'</b><small>'+g[0].city+', '+g[0].country+'</small></div>'+g.map(x=>'<div class="dupRecord"><span><strong>'+x.name+'</strong><small>'+x.id+' · '+(x._source||'source unknown')+' · '+(x.precision||'unknown')+'</small></span><button data-dup-open="'+x.id+'">✎</button></div>').join('')+'</div>').join(''):'<div class="pendingEmpty">✓ '+(currentLang==='es'?'No se han detectado duplicados claros':'No clear duplicates detected')+'</div>';el.querySelectorAll('[data-dup-open]').forEach(b=>b.onclick=()=>editAdminRecord(b.dataset.dupOpen))}document.getElementById('scanDuplicates').onclick=renderDuplicates;
function updateAdminQuality(){const el=document.getElementById('adminQualityStrip');if(!el)return;const ps=['exact','address','city','region','unknown'];const labels=currentLang==='es'?{exact:'Exacta',address:'Dirección',city:'Por ciudad',region:'Regional',unknown:'Por revisar'}:{exact:'Exact',address:'Address',city:'City-level',region:'Region-level',unknown:'Unknown'};el.innerHTML=ps.map(p=>{const n=data.filter(x=>(x.precision||'unknown')===p).length;return '<button data-qprecision="'+p+'"><b>'+n.toLocaleString()+'</b><small>'+labels[p]+'</small></button>'}).join('');el.querySelectorAll('[data-qprecision]').forEach(b=>b.onclick=()=>{document.getElementById('adminPrecision').value=b.dataset.qprecision;renderAdminRows('quality')})}
function populateAdminCountries(){const e=document.getElementById('adminCountry');if(!e)return;const v=e.value;e.innerHTML='<option value="all">All countries</option>'+[...new Set(data.map(x=>x.country))].sort().map(x=>'<option>'+x+'</option>').join('');if([...e.options].some(o=>o.value===v))e.value=v}
function openAdminWorkspace(mode){
 adminPanel.classList.add('workspace');adminWorkspace.classList.add('open');
 if(mode==='institutions'||mode==='quality'){populateAdminCountries();updateAdminQuality();updateDuplicateCount();updateQualityPriority();document.getElementById('duplicateTools').style.display=mode==='quality'?'block':'none';document.getElementById('qualityPriority').style.display=mode==='quality'?'grid':'none';document.getElementById('adminWorkTitle').textContent=mode==='quality'?'Data quality':'Institutions';document.getElementById('adminWorkSub').textContent=mode==='quality'?'Review location precision and records':'Search and edit public map records';renderAdminRows(mode)}
 if(mode==='teachers'){document.getElementById('duplicateTools').style.display='none';document.getElementById('qualityPriority').style.display='none';document.getElementById('adminWorkTitle').textContent='Pending submissions';document.getElementById('adminWorkSub').textContent='Approve, edit or reject community registrations';adminWorkspace.querySelector('.adminControls').style.display='none';document.getElementById('adminQualityStrip').innerHTML='';renderPendingSubmissions()}
 if(mode==='export'){document.getElementById('duplicateTools').style.display='none';document.getElementById('qualityPriority').style.display='none';document.getElementById('adminWorkTitle').textContent='Export data';document.getElementById('adminWorkSub').textContent='Filter and select exactly what you want';adminWorkspace.querySelector('.adminControls').style.display='none';renderExportBuilder()}
}
function closeAdminWorkspace(){adminPanel.classList.remove('workspace');adminWorkspace.classList.remove('open');adminWorkspace.querySelector('.adminControls').style.display='grid'}
document.getElementById('adminBack').onclick=closeAdminWorkspace;
document.querySelectorAll('.adminGrid button').forEach(b=>b.onclick=()=>{const m=b.dataset.admin;if(['institutions','quality','export','teachers'].includes(m))openAdminWorkspace(m)});
function renderPendingSubmissions(){const rows=pendingSubmissions(),el=document.getElementById('adminTable');el.innerHTML=rows.length?rows.map(x=>'<div class="pendingSubmission"><div><strong>'+x.name+'</strong><small>'+x.city+', '+x.country+(x.institution?' · '+x.institution:'')+'</small><em>🔒 '+x.email+' · '+x.visibility+'</em></div><div><button data-pa="'+x.id+'">Approve</button><button data-pr="'+x.id+'">Reject</button></div></div>').join(''):'<div class="pendingEmpty">✓ No pending submissions</div>';el.querySelectorAll('[data-pa]').forEach(b=>b.onclick=()=>approveSubmission(b.dataset.pa));el.querySelectorAll('[data-pr]').forEach(b=>b.onclick=()=>rejectSubmission(b.dataset.pr))}function approveSubmission(id){let v=pendingSubmissions(),x=v.find(r=>r.id===id);if(!x)return;if(x.visibility!=='private'){data.push({id:'TEACHER-'+Date.now(),name:x.name,type:'teacher',city:x.city,country:x.country,lat:0,lng:0,web:x.web||'',verified:false,precision:x.visibility==='country'?'country':'city',program:'Spanish / ELE',institution:x.institution||'',visibility:x.visibility})}v=v.filter(r=>r.id!==id);savePendingSubmissions(v);render();renderPendingSubmissions()}function rejectSubmission(id){savePendingSubmissions(pendingSubmissions().filter(r=>r.id!==id));renderPendingSubmissions()}
function renderAdminRows(mode='institutions'){
 const q=document.getElementById('adminSearch').value.toLowerCase(),typ=document.getElementById('adminType').value,country=document.getElementById('adminCountry')?.value||'all',precision=document.getElementById('adminPrecision')?.value||'all';
 let rows=data.filter(x=>(typ==='all'||x.type===typ)&&(country==='all'||x.country===country)&&(precision==='all'||(x.precision||'unknown')===precision)&&(!q||[x.name,x.city,x.country,x.id].some(v=>(v||'').toLowerCase().includes(q))));
 if(mode==='quality')rows=rows.sort((a,b)=>(a.precision==='exact'?1:0)-(b.precision==='exact'?1:0));
 document.getElementById('adminTable').innerHTML=rows.slice(0,300).map(x=>'<div class="adminRow"><div><strong>'+x.name+'</strong><small>'+x.city+', '+x.country+' · '+(x.precision||'unknown')+'</small></div><span class="type">'+x.type+'</span><button data-edit="'+x.id+'">✎</button></div>').join('');
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editAdminRecord(b.dataset.edit));
}
document.getElementById('adminSearch').oninput=()=>renderAdminRows();['adminType','adminCountry','adminPrecision'].forEach(id=>document.getElementById(id).onchange=()=>renderAdminRows());
function editAdminRecord(id){const x=data.find(r=>r.id===id);if(!x)return;document.getElementById('adminTable').innerHTML='<div class="adminEdit"><label>Name<input id="aeName" value="'+escAttr(x.name)+'"></label><label>City<input id="aeCity" value="'+escAttr(x.city)+'"></label><label>Country<input id="aeCountry" value="'+escAttr(x.country)+'"></label><label>Address<input id="aeAddress" value="'+escAttr(x.address||'')+'"></label><label>Latitude<input id="aeLat" type="number" step="any" value="'+x.lat+'"></label><label>Longitude<input id="aeLng" type="number" step="any" value="'+x.lng+'"></label><label>Website<input id="aeWeb" value="'+escAttr(x.web||'')+'"></label><div class="adminEditActions"><button class="adminSave" id="aeSave">Save locally</button><button class="adminDelete" id="aeDelete">Remove locally</button></div></div>';document.getElementById('aeSave').onclick=()=>{Object.assign(x,{name:document.getElementById('aeName').value,city:document.getElementById('aeCity').value,country:document.getElementById('aeCountry').value,address:document.getElementById('aeAddress').value,lat:+document.getElementById('aeLat').value,lng:+document.getElementById('aeLng').value,web:document.getElementById('aeWeb').value,precision:'exact'});render();renderAdminRows()};document.getElementById('aeDelete').onclick=()=>{data=data.filter(r=>r.id!==id);render();renderAdminRows()}}
function escAttr(v){return String(v??'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;')}
function exportFields(){return ['id','name','type','city','country','address','lat','lng','precision','web','verified','program']}
let exportSelected=new Set();
function renderExportBuilder(){
 const countries=[...new Set(data.map(x=>x.country))].sort();
 adminWorkspace.querySelector('.adminTable').innerHTML='<div class="exportBuilder"><div class="exportFilters"><select id="exType"><option value="all">All types</option><option value="school">Schools</option><option value="university">Universities</option><option value="language">Language schools</option><option value="official">Official institutions</option><option value="association">Associations</option><option value="teacher">Teachers</option></select><select id="exCountry"><option value="all">All countries</option>'+countries.map(x=>'<option>'+x+'</option>').join('')+'</select><input id="exCity" placeholder="City"><input id="exSearch" placeholder="Search name…"></div><div class="exportActions"><button id="exAll">Select visible</button><button id="exNone">Clear all</button><strong id="exCount">0 selected</strong></div><div class="exportList" id="exportList"></div><div class="exportDownload"><button class="exportXlsx" id="downloadXlsx">⇩ Excel (.xlsx)</button><button class="exportCsv" id="downloadCsv">⇩ CSV</button></div></div>';
 ['exType','exCountry'].forEach(id=>document.getElementById(id).onchange=renderExportList);['exCity','exSearch'].forEach(id=>document.getElementById(id).oninput=renderExportList);
 document.getElementById('exAll').onclick=()=>{getExportVisible().forEach(x=>exportSelected.add(x.id));renderExportList()};document.getElementById('exNone').onclick=()=>{exportSelected.clear();renderExportList()};
 document.getElementById('downloadCsv').onclick=downloadSelectedCsv;document.getElementById('downloadXlsx').onclick=downloadSelectedXlsx;renderExportList();
}
function getExportVisible(){const typ=document.getElementById('exType')?.value||'all',country=document.getElementById('exCountry')?.value||'all',city=(document.getElementById('exCity')?.value||'').toLowerCase(),q=(document.getElementById('exSearch')?.value||'').toLowerCase();return data.filter(x=>(typ==='all'||x.type===typ)&&(country==='all'||x.country===country)&&(!city||(x.city||'').toLowerCase().includes(city))&&(!q||(x.name||'').toLowerCase().includes(q)))}
function renderExportList(){const rows=getExportVisible(),el=document.getElementById('exportList');if(!el)return;el.innerHTML=rows.map(x=>'<label class="exportItem"><input type="checkbox" data-ex="'+x.id+'" '+(exportSelected.has(x.id)?'checked':'')+'><span><strong>'+x.name+'</strong><small>'+x.city+', '+x.country+'</small></span><em>'+x.type+'</em></label>').join('');el.querySelectorAll('[data-ex]').forEach(cb=>cb.onchange=()=>{cb.checked?exportSelected.add(cb.dataset.ex):exportSelected.delete(cb.dataset.ex);updateExportCount()});updateExportCount()}
function updateExportCount(){const e=document.getElementById('exCount');if(e)e.textContent=exportSelected.size+' selected'}
function selectedExportData(){return data.filter(x=>exportSelected.has(x.id))}
function downloadSelectedCsv(){const selected=selectedExportData();if(!selected.length)return;const fields=exportFields(),rows=[fields.join(','),...selected.map(x=>fields.map(f=>'"'+String(x[f]??'').replace(/"/g,'""')+'"').join(','))];const blob=new Blob([rows.join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ATLAS_ELE_Selected_Data.csv';a.click();URL.revokeObjectURL(a.href)}
function downloadSelectedXlsx(){const selected=selectedExportData();if(!selected.length)return;const fields=exportFields(),rows=selected.map(x=>Object.fromEntries(fields.map(f=>[f,x[f]??''])));const ws=XLSX.utils.json_to_sheet(rows),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'ATLAS ELE');XLSX.writeFile(wb,'ATLAS_ELE_Selected_Data.xlsx')}
